import io
import json
import os
import signal
import sys
import traceback
from contextlib import redirect_stderr, redirect_stdout


class REPLWorker:
    def __init__(self):
        self.globals = {
            "__name__": "__main__",
            "__doc__": None,
            "__package__": None,
            "__builtins__": __builtins__,
        }
        self.should_shutdown = False
        self._setup_signals()

