require "set"

files = Dir.glob("{app/views,app/mailers,app/helpers,app/controllers,app/models,app/jobs}/**/*").select { |f| File.file?(f) }
strings = Hash.new { |h,k| h[k] = [] }

attr_re =/(?:aria-label|title|placeholder|alt|data-tooltip-text|data-title|data-label)="([^"]*[A-Za-z][^"]*)"/
text_re = />\s*([^<>{}%]*[A-Za-z][^<>{}%]*?)\s*</
ruby_re = /["']([A-Z][^"']{2,}?)["']/

files.each do |file|
  content = File.read(file)
  content.scan(attr_re) { |m| strings[m[0].strip] << file }
  content.scan(text_re) { |m| strings[m[0].strip] << file if m[0].strip =~ /\A[A-Za-z]/ }
  if file !~ /\.erb\z/ || content.include?("<%")
    content.scan(ruby_re) { |m| strings[m[0].strip] << file }
  end
end

File.write("/tmp/strings.txt", strings.keys.sort.map { |s| "#{strings[s].size}\t#{s}" }.join("\n"))
puts "unique: #{strings.size}"
puts "files: #{files.size}"
